/// Whether to show the legacy center seek HUD.
///
/// When false, the scrubbing feedback can be surfaced elsewhere (e.g. in
/// the crumb / progress area) via [onSeekPreview].
final bool showCenterSeekHud;

/// Optional during-gesture callback for target/duration/progress.
///
/// Called at drag start and every drag update.
final void Function(Duration target, Duration duration, double fraction)?
    onSeekPreview;

/// Optional callback invoked on drag end.
///
/// Use to clear temporary feedback.
final VoidCallback? onSeekPreviewEnd;

/// Optional external driver for the edge flash (prev/next from a drag).
final HeroFlashController? flashController;

edits.oldText:
void onSeekStart(DragStartDetails _) {
  seekStartMs.value = positionMs();
  seekDurationMs.value = durationMs();
  seekAccumDx.value = 0;
  seekTargetMs.value = seekStartMs.value;
  seeking.value = true;
}

edits.newText:
void onSeekStart(DragStartDetails _) {
  seekStartMs.value = positionMs();
  seekDurationMs.value = durationMs();
  seekAccumDx.value = 0;
  seekTargetMs.value = seekStartMs.value;
  seeking.value = true;

  final duration = Duration(milliseconds: seekDurationMs.value);
  final target = Duration(milliseconds: seekTargetMs.value);
  final fraction = seekDurationMs.value <= 0
      ? 0.0
      : (seekTargetMs.value / seekDurationMs.value)
          .clamp(0.0, 1.0);
  onSeekPreview?.call(target, duration, fraction);
}

edits.oldText:
void onSeekUpdate(DragUpdateDetails d) {
  if (seekDurationMs.value <= 0) return;
  seekAccumDx.value += d.primaryDelta ?? 0;
  final raw = seekStartMs.value +
      (seekAccumDx.value / width.value) * seekDurationMs.value;
  seekTargetMs.value =
      raw.clamp(0, seekDurationMs.value.toDouble()).round();
}

edits.newText:
void onSeekUpdate(DragUpdateDetails d) {
  if (seekDurationMs.value <= 0) return;
  seekAccumDx.value += d.primaryDelta ?? 0;
  final raw = seekStartMs.value +
      (seekAccumDx.value / width.value) * seekDurationMs.value;
  seekTargetMs.value =
      raw.clamp(0, seekDurationMs.value.toDouble()).round();

  final duration = Duration(milliseconds: seekDurationMs.value);
  final target = Duration(milliseconds: seekTargetMs.value);
  final fraction =
      (seekTargetMs.value / seekDurationMs.value).clamp(0.0, 1.0);
  onSeekPreview?.call(target, duration, fraction);
}

edits.oldText:
void onSeekEnd(DragEndDetails _) {
  final hadDuration = seekDurationMs.value > 0;
  final target = seekTargetMs.value;
  seeking.value = false;
  if (hadDuration) {
    onSeek(Duration(milliseconds: target));
  }
}

edits.newText:
